SELECT * FROM transactions

  household_id = #{householdId} AND deleted_at IS NULL
  AND transacted_on BETWEEN #{from} AND #{to}

    AND (account_id = #{accountId} OR to_account_id = #{accountId})


    AND category_id = #{categoryId}


ORDER BY transacted_on DESC, id DESC

SELECT COALESCE(SUM(amount), 0) FROM transactions
WHERE household_id = #{householdId} AND deleted_at IS NULL AND type = #{type}
  AND transacted_on BETWEEN #{from} AND #{to}
